92	function drawCards(cards, count) {
93	  const pool = [...cards];
94	  for (let i = pool.length - 1; i > 0; i--) {
95	    const j = Math.floor(Math.random() * (i + 1));
96	    [pool[i], pool[j]] = [pool[j], pool[i]];
97	  }
98	  return pool.slice(0, count);
99	}
